// Canonical API catalog for sid-be.
//
// One entry per registered route, tagged with:
//   endpoint, method, category, subcategory,
//   description, upstream, upstream_name,
//   auth_required, rate_limit, cache_ttl_sec,
//   params, example_url, tags
//
// Consumed by:
//   • GET /api/api-catalog (public discovery)
//   • System Oracle context bundle (so the LLM cites accurate upstream URLs
//     and rate limits instead of hallucinating)
//   • FE settings dashboard (Endpoints tab — pairs each row with a metrics
//     row keyed on the same `endpoint` string)
//
// Rules:
//   • URL patterns only — never bake secrets (API keys, tokens) into a value.
//   • `upstream` may include a `{slug}` template; keep those literal so the
//     Oracle can quote them verbatim.
//   • Unknown-value fields must use null, not a made-up string.

import { tools as OSINT_TOOLS } from '../osint/index.js';

