function buildOsintCatalog() {
  const entries = [];
  for (const [name, tool] of Object.entries(OSINT_TOOLS)) {
    const meta = OSINT_TOOL_META[name] || {};
    const params = (tool.paramSchema || []).map(p => ({
      name:     p.key,
      type:     p.type || 'text',
      required: !!p.required,
      source:   p.source || 'query',
      example:  p.placeholder || null,
      helper:   p.helper || null,
    }));
    // Build a sample URL — walk the paramSchema in order and drop the
    // placeholder into path-source keys; keep the query for query-source ones.
    const pathParts = params.filter(p => p.source === 'path').map(p => encodeURIComponent(p.example || p.name));
    const queryPairs = params.filter(p => p.source === 'query').filter(p => p.example);
    const qs = queryPairs.length ? `?${queryPairs.map(p => `${p.name}=${encodeURIComponent(p.example)}`).join('&')}` : '';
    entries.push({
      endpoint:       '/api/osint/tool/:name',   // shared dispatcher endpoint pattern
      route_key:      `/api/osint/tool/${name}`, // for lookup + docs
      method:         'GET',
      category:       'osint',
      subcategory:    meta.subcategory || 'general',
      description:    tool.description,
      upstream:       meta.upstream || null,
      upstream_name:  meta.upstream_name || null,
      auth_required:  false,
      rate_limit:     meta.rate_limit || null,
      cache_ttl_sec:  meta.cache_ttl_sec ?? null,
      params,
      example_url:    `/api/osint/tool/${name}${pathParts.length ? '/' + pathParts.join('/') : ''}${qs}`,
      tags:           meta.tags || ['osint'],
      needs_key:      tool.needsKey || null,
      tool_name:      name,
    });
  }
  return entries;
}

