// ── Assemble ──────────────────────────────────────────────────────
// Order: OSINT tools first (heaviest slice, ~30 entries), then REST
// aliases, then everything else. Preserved as insertion order in the
// public array so callers don't have to sort.

let _catalog = null;

/**
 * Return the fully-assembled catalog (lazy — OSINT tools import happens
 * at first call, which lines up with when the express server has already
 * finished booting).
 */
export function getCatalog() {
  if (_catalog) return _catalog;
  const merged = [
    ...buildOsintCatalog(),
    ...OSINT_REST,
    ...NASA,
    ...PROXY,
    ...HEALTH_AUTH,
    ...AI,
    ...TOOLS,
    ...CREATION_LANES,
    ...MISC,
    ...CHESS,
    ...OPERATIONS,
    ...GPU_WORKER,
  ];
  // Normalize: strip any accidentally-set env values that made it through
  // and never surface non-serialisable fields.
  _catalog = merged.map(e => ({
    endpoint:       e.endpoint,
    method:         e.method,
    category:       e.category,
    subcategory:    e.subcategory || null,
    description:    e.description || null,
    upstream:       e.upstream || null,
    upstream_name:  e.upstream_name || null,
    auth_required:  e.auth_required ?? false,
    rate_limit:     e.rate_limit || null,
    cache_ttl_sec:  e.cache_ttl_sec ?? null,
    params:         Array.isArray(e.params) ? e.params : [],
    example_url:    e.example_url || null,
    tags:           Array.isArray(e.tags) ? e.tags : [],
    // OSINT tool-specific extras kept only when populated
    ...(e.tool_name  ? { tool_name:  e.tool_name }  : {}),
    ...(e.route_key  ? { route_key:  e.route_key }  : {}),
    ...(e.needs_key  ? { needs_key:  e.needs_key }  : {}),
  }));
  return _catalog;
}

// Named export in the same shape the brief specified — resolved once at
// module load, so `API_CATALOG.length` etc. keep working for existing
// consumers even without calling getCatalog().
export const API_CATALOG = getCatalog();

// Handy lookup helpers used by the Oracle context bundler.
export function findByEndpoint(endpoint) {
  return API_CATALOG.filter(e => e.endpoint === endpoint);
}

export function findByCategory(category) {
  return API_CATALOG.filter(e => e.category === category);
}

export function countByCategory() {
  const out = {};
  for (const e of API_CATALOG) out[e.category] = (out[e.category] || 0) + 1;
  return out;
}
